// Class 9 Science practice bank, part 4: Atom to Earth as a System. Extra questions for year-long practice.
(function () {
  const AR_OPTS = ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."];
  let n = 4 - 1;
  // M(level, question, right answer, three wrong answers, explanation, objective?): the right answer is stored at a varying position.
  function M(level, q, right, wrong, explain, obj) {
    const at = (n++) % 4;
    const options = wrong.slice();
    options.splice(at, 0, right);
    const o = { q, options, answer: at, explain, level };
    if (obj) o.obj = obj;
    return o;
  }
  // AR(level, assertion, reason, answer index, explanation, objective?): assertion–reason with fixed options.
  function AR(level, a, r, answer, explain, obj) {
    const o = { q: "Assertion (A): " + a + "\nReason (R): " + r, options: AR_OPTS, answer, explain, level, keepOrder: true };
    if (obj) o.obj = obj;
    return o;
  }
  function W(marks, q, a, type, obj) {
    const o = { q, a, marks };
    if (type) o.type = type;
    if (obj) o.obj = obj;
    return o;
  }
  StudyData.addPractice(9, "science", {
  "journey-inside-the-atom": {
    mcq: [
      M(1, "In which atomic model are electrons embedded in a positively charged sphere?", "Thomson's model", ["Rutherford's model", "Bohr's model", "Dalton's model"], "Thomson pictured electrons embedded in a positive sphere. Rutherford's gold foil experiment tested this."),
      M(1, "Which scientist proposed that electrons move in fixed energy levels?", "Bohr", ["Thomson", "Chadwick", "Dalton"], "Bohr's shells (K, L, M, N…) explain the stability of atoms."),
      M(1, "The subatomic particle with no electric charge is the", "neutron", ["proton", "electron", "nucleus"], "Neutrons are neutral. Protons are positive and electrons are negative."),
      M(1, "The mass number of an atom is the number of", "protons plus neutrons", ["protons only", "electrons only", "neutrons minus protons"], "Mass number A = protons + neutrons (nucleons)."),
      M(1, "Which scientist discovered the atomic nucleus by scattering α-particles from gold foil?", "Rutherford", ["Thomson", "Chadwick", "Bohr"], "Rutherford's gold foil experiment (1911) showed that the atom has a small, dense, positive nucleus."),
      M(1, "The nucleus of an atom is about how many times smaller than the atom in diameter?", "About 10⁵ times", ["About 10 times", "About 100 times", "About the same size"], "The atom is about 10⁻¹⁰ m and the nucleus about 10⁻¹⁵ m across."),
      M(1, "Which isotope is used as a nuclear fuel?", "Uranium-235", ["Cobalt-60", "Carbon-12", "Deuterium"], "Uranium-235 is used as nuclear fuel, and cobalt-60 is used in cancer treatment."),
      M(2, "A chlorine atom (Z = 17) gains one electron to form Cl⁻. The number of electrons in Cl⁻ is", "18", ["17", "16", "35"], "A neutral Cl atom has 17 electrons. After gaining one it has 18."),
      M(2, "An atom of ²⁴₁₂Mg has", "12 protons, 12 neutrons and 12 electrons", ["12 protons, 24 neutrons and 12 electrons", "24 protons, 12 neutrons and 24 electrons", "12 protons, 12 neutrons and 24 electrons"], "Protons = electrons = Z = 12. Neutrons = 24 − 12 = 12."),
      M(2, "The electronic configuration of aluminium (Z = 13) is", "2, 8, 3", ["2, 8, 2", "2, 11", "2, 3, 8"], "The K shell takes 2 and the L shell takes 8. The remaining 3 go to the M shell."),
      M(2, "The electronic configuration of argon (Z = 18) is 2, 8, 8. Its valency is", "0", ["8", "1", "2"], "Its outer shell is full, so it does not gain, lose or share electrons."),
      M(2, "An atom has the configuration 2, 8, 6. Its valency is", "2", ["6", "8", "4"], "It needs 2 more electrons to complete its octet, so its valency is 2."),
      M(2, "A sodium atom (Z = 11) loses one electron to form Na⁺. The number of electrons in Na⁺ is", "10", ["11", "12", "1"], "Na has 11 electrons. After losing one it has 10."),
      M(2, "Which pair of atoms are isotopes?", "¹²₆C and ¹⁴₆C", ["¹⁴₆C and ¹⁴₇N", "⁴⁰₂₀Ca and ⁴⁰₁₈Ar", "¹²₆C and ¹⁴₇N"], "Isotopes have the same atomic number and different mass numbers. ¹⁴C and ¹⁴N are isobars."),
      M(2, "Two isotopes of an element differ in their number of", "neutrons", ["protons", "electrons", "valence electrons"], "The atomic number is the same, so the protons are the same, and so are the electrons. Only the neutrons differ."),
      M(2, "Most of the α-particles passed straight through the gold foil. This showed that", "most of the atom is empty space", ["the atom is a solid sphere", "all the atoms are positive", "the foil was too thick"], "The nucleus is tiny, so most α-particles did not meet it."),
      M(2, "Calcium (Z = 20) has its electrons arranged in how many shells?", "4 (K, L, M and N)", ["2", "3", "5"], "The configuration is 2, 8, 8, 2, so four shells are used."),
      M(2, "Neon has two isotopes: ²⁰Ne (90%) and ²²Ne (10%). Its average atomic mass is", "20.2 u", ["21 u", "20 u", "22 u"], "Average = (20 × 0.90) + (22 × 0.10) = 18 + 2.2 = 20.2 u."),
      M(2, "Which of these atoms has a valency of zero?", "Neon (2, 8)", ["Sodium (2, 8, 1)", "Magnesium (2, 8, 2)", "Chlorine (2, 8, 7)"], "Neon has a full outer shell, so it does not gain, lose or share electrons."),
      M(3, "A magnesium atom (Z = 12) forms the ion Mg²⁺. The electronic configuration of Mg²⁺ is", "2, 8", ["2, 8, 2", "2, 8, 4", "2, 6"], "Mg is 2, 8, 2. Losing 2 electrons from the outer shell gives 2, 8."),
      M(3, "An atom has 15 protons and a mass number of 31. How many neutrons does it have?", "16", ["15", "31", "46"], "Neutrons = 31 − 15 = 16."),
      AR(3, "Most of the α-particles passed straight through the gold foil.", "An atom is mostly empty space.", 0, "Both are true, and the empty space is why most of the particles went straight."),
      AR(3, "Isotopes of an element have different physical properties.", "Isotopes have different mass numbers.", 0, "Both are true. Differences in mass give different physical properties, such as density."),
      AR(3, "The nucleus of an atom contains electrons.", "Electrons revolve around the nucleus.", 3, "A is false, since the nucleus has protons and neutrons. R is true."),
      AR(3, "An atom is electrically neutral.", "The number of protons in an atom is equal to the number of electrons.", 0, "Both are true. Equal positive and negative charges cancel."),
    ],
    written: [
      W(1, "State the maximum number of electrons that can be present in the N shell.", "Using 2n² with n = 4: 2 × 16 = 32 electrons.", "short"),
      W(1, "What did Chadwick discover and in which year?", "Chadwick discovered the neutron in 1932.", "short"),
      W(2, "For ³¹₁₅P state the number of protons, neutrons and electrons.", "Protons = Z = 15. Electrons = 15 (neutral atom). Neutrons = A − Z = 31 − 15 = 16.", "short"),
      W(2, "Write the electronic configuration and valency of aluminium (Z = 13).", "The configuration is 2, 8, 3. It has 3 electrons in the outer shell, which it loses easily, so its valency is 3.", "short"),
      W(2, "Why are noble gases such as neon and argon chemically unreactive?", "Their outer shells are full (8 electrons, or 2 for helium), which is a stable configuration. They do not need to gain, lose or share electrons, so their valency is zero.", "short"),
      W(2, "An element has two isotopes of mass 40 u (60%) and 42 u (40%). Find its average atomic mass.", "Average = (40 × 0.60) + (42 × 0.40) = 24 + 16.8 = 40.8 u.", "short"),
      W(3, "Distinguish between isotopes and isobars with an example of each.", "Isotopes are atoms of the same element with the same atomic number but different mass numbers, such as ¹²C and ¹⁴C. Isobars are atoms of different elements with the same mass number but different atomic numbers, such as ⁴⁰Ca and ⁴⁰Ar. Isotopes have the same chemical properties, but isobars do not.", "short"),
      W(3, "The diameter of an atom is about 10⁻¹⁰ m and that of its nucleus about 10⁻¹⁵ m. How many times smaller is the nucleus? What does this show about the atom?", "10⁻¹⁰ ÷ 10⁻¹⁵ = 10⁵, so the nucleus is about 10⁵ times smaller. This shows that most of the atom is empty space, and that nearly all the mass is in the tiny nucleus.", "short"),
      W(4, "Case study: The table gives four species. A: Z = 6, A = 12. B: Z = 6, A = 14. C: Z = 7, A = 14. D: Z = 8, A = 16.\n(i) Which two are isotopes?\n(ii) Which two are isobars?\n(iii) How many neutrons does B have?", "(i) A and B, which have the same atomic number (6) and different mass numbers.\n(ii) B and C, which have the same mass number (14) and different atomic numbers.\n(iii) Neutrons in B = 14 − 6 = 8.", "case"),
      W(5, "Write the electronic configuration and valency of magnesium (Z = 12), sulphur (Z = 16) and argon (Z = 18). Explain what an octet is and why it makes an atom stable.", "Magnesium: 2, 8, 2; valency 2 (it loses 2 electrons).\nSulphur: 2, 8, 6; valency 2 (it gains 2 electrons or shares them).\nArgon: 2, 8, 8; valency 0.\nAn octet is a full outer shell of 8 electrons (2 for helium). Such a configuration is stable, so the atom is largely unreactive. Other atoms combine, by gaining, losing or sharing electrons, to reach it.", "long"),
    ],
  },
    "atomic-foundations-of-matter": {
    mcq: [
      M(1, "The law of definite proportions was stated by", "Proust", ["Lavoisier", "Dalton", "Rutherford"], "Proust showed that a compound always has its elements in a fixed ratio by mass."),
      M(1, "According to Dalton's theory, all atoms of an element are", "alike in mass", ["different in mass", "divisible into protons only", "created in chemical reactions"], "This idea was refined later, since isotopes exist."),
      M(1, "Which of these substances has covalent bonds?", "Water", ["Sodium chloride", "Magnesium chloride", "Calcium oxide"], "Water is formed by the sharing of electrons between hydrogen and oxygen atoms."),
      M(1, "An anion is an ion that is", "negatively charged", ["positively charged", "neutral", "a molecule"], "An atom that gains electrons becomes a negative ion, an anion."),
      M(1, "A bond formed by the transfer of electrons is", "an ionic bond", ["a covalent bond", "a nuclear bond", "a magnetic bond"], "The atom that loses electrons becomes a cation and the one that gains them becomes an anion."),
      M(1, "An ionic compound conducts electricity when it is", "molten or dissolved in water", ["solid", "powdered", "dry"], "In these states the ions are free to move."),
      M(1, "The term 'formula unit' is used for", "ionic compounds", ["gases only", "covalent molecules", "elements"], "Ionic compounds form crystals of ions, not molecules, so we speak of a formula unit."),
      M(2, "2 g of hydrogen combine with 16 g of oxygen to give 18 g of water. How much oxygen is needed to make 9 g of water?", "8 g", ["16 g", "4 g", "2 g"], "9 g is half of 18 g, so half the oxygen is needed: 8 g. This also follows the 1 : 8 ratio."),
      M(2, "Hydrogen and oxygen combine in the mass ratio 1 : 8 to form water. The oxygen needed to react completely with 5 g of hydrogen is", "40 g", ["5 g", "1.6 g", "45 g"], "Oxygen = 5 × 8 = 40 g. This forms 45 g of water."),
      M(2, "In carbon dioxide, carbon and oxygen are present in the ratio 3 : 8 by mass. The mass of carbon in 22 g of carbon dioxide is", "6 g", ["16 g", "3 g", "8 g"], "Total parts = 11. Carbon = 22 × 3/11 = 6 g."),
      M(2, "The formula unit mass of Na₂CO₃ (Na = 23, C = 12, O = 16 u) is", "106 u", ["83 u", "95 u", "62 u"], "2 × 23 + 12 + 3 × 16 = 46 + 12 + 48 = 106 u."),
      M(2, "The molecular mass of three molecules of water (H = 1, O = 16 u) is", "54 u", ["18 u", "19 u", "27 u"], "One molecule of H₂O = 2 + 16 = 18 u, so three molecules = 3 × 18 = 54 u."),
      M(2, "The formula of aluminium chloride (Al³⁺ and Cl⁻) is", "AlCl₃", ["Al₃Cl", "AlCl", "Al₃Cl₃"], "Criss-cross the valencies: Al takes 1 and Cl takes 3, so the formula is AlCl₃."),
      M(2, "The formula of magnesium oxide (Mg²⁺ and O²⁻) is", "MgO", ["Mg₂O", "MgO₂", "Mg₂O₂"], "The criss-cross of 2 and 2 simplifies to 1 : 1, so the formula is MgO."),
      M(2, "A solid ionic compound does not conduct electricity because", "its ions are fixed in the crystal and cannot move", ["it has no ions", "it has free electrons that cannot move", "it is a gas"], "Only when the ions are free, in the molten state or in solution, can the compound conduct."),
      M(2, "Which property is typical of an ionic compound?", "A high melting point", ["A low melting point", "Being a gas at room temperature", "Being a poor conductor when molten"], "Ionic compounds are hard and brittle with high melting points."),
      M(2, "Dalton's theory explains the law of conservation of mass because atoms", "are neither created nor destroyed in a chemical reaction", ["are divisible in a reaction", "change into other atoms", "are made only of electrons"], "The atoms are only rearranged, so the total mass remains the same."),
      M(2, "Which part of Dalton's theory was later found to need change?", "All atoms of an element are alike in mass", ["Atoms combine in simple whole-number ratios", "Matter is made of tiny atoms", "Atoms are not created or destroyed in a chemical reaction"], "Isotopes show that atoms of the same element can have different masses."),
      M(2, "A sodium atom becomes Na⁺ by", "losing one electron", ["gaining one electron", "gaining one proton", "losing one proton"], "Losing an electron leaves more protons than electrons, so the ion is positive."),
      M(2, "Samples of carbon dioxide from marble and from burning charcoal contain carbon and oxygen in the same mass ratio. This illustrates the law of", "definite proportions", ["conservation of mass", "multiple bonding", "the octet"], "A compound has a fixed ratio of elements, whatever its source."),
      M(3, "In water, the ratio of hydrogen to oxygen is 1 : 8 by mass. The mass of oxygen in 90 g of water is", "80 g", ["10 g", "72 g", "8 g"], "Oxygen = 90 × 8/9 = 80 g."),
      M(3, "The formula unit mass of Mg(NO₃)₂ (Mg = 24, N = 14, O = 16 u) is", "148 u", ["86 u", "110 u", "134 u"], "24 + 2 × (14 + 48) = 24 + 124 = 148 u."),
      M(3, "Carbon and oxygen combine in the ratio 3 : 8 by mass to form carbon dioxide. The mass of oxygen needed to burn 15 g of carbon completely is", "40 g", ["5.6 g", "120 g", "45 g"], "15 ÷ 3 = 5, so oxygen = 5 × 8 = 40 g. It forms 55 g of CO₂."),
      M(3, "The formula of magnesium nitrate (Mg²⁺ and NO₃⁻) is", "Mg(NO₃)₂", ["MgNO₃", "Mg₂NO₃", "Mg₂(NO₃)"], "Criss-cross the valencies: 1 of Mg and 2 of NO₃. The NO₃ group is put in brackets."),
      AR(3, "The law of definite proportions does not hold for mixtures.", "The composition of a mixture can vary.", 0, "Both are true. Only a compound has a fixed ratio."),
      AR(3, "A molecule of water has covalent bonds.", "In water, hydrogen and oxygen atoms share electrons.", 0, "Both are true, and the sharing of electrons is what makes the bonds covalent."),
    ],
    written: [
      W(1, "State the law of conservation of mass.", "In a chemical reaction mass is neither created nor destroyed, so the total mass of the reactants equals the total mass of the products.", "short"),
      W(1, "Write the formula of calcium oxide (Ca²⁺ and O²⁻).", "CaO (the criss-cross of 2 and 2 simplifies to 1 : 1).", "short"),
      W(2, "Write the formula of aluminium chloride using the criss-cross method.", "Al has valency 3 and Cl has valency 1. Criss-crossing gives Al₁Cl₃, that is AlCl₃.", "short"),
      W(2, "Calculate the formula unit mass of magnesium hydroxide, Mg(OH)₂ (Mg = 24, O = 16, H = 1 u).", "24 + 2 × (16 + 1) = 24 + 34 = 58 u.", "short"),
      W(2, "Water has hydrogen and oxygen in the mass ratio 1 : 8. Find the mass of hydrogen and of oxygen in 27 g of water.", "Total parts = 1 + 8 = 9. Hydrogen = 27 × 1/9 = 3 g. Oxygen = 27 × 8/9 = 24 g.", "short"),
      W(2, "2 g of hydrogen combine with 16 g of oxygen to give 18 g of water. Which law does this illustrate? How much hydrogen and oxygen are needed for 9 g of water?", "It illustrates the law of conservation of mass (2 + 16 = 18). For 9 g of water, half the amounts are needed: 1 g of hydrogen and 8 g of oxygen.", "short"),
      W(3, "Explain how a covalent bond forms in a hydrogen molecule, H₂.", "Each hydrogen atom has one electron. The two atoms share their electrons so that each has a stable arrangement. The shared pair holds the atoms together as a covalent bond, forming a neutral molecule, H₂.", "short"),
      W(3, "Write three differences between ionic and covalent compounds.", "Ionic compounds have high melting points, are hard and brittle, are usually soluble in water and conduct electricity when molten or dissolved. Covalent compounds usually have low melting points, are often insoluble in water and are poor conductors of electricity.", "short"),
      W(4, "Case study: Carbon dioxide from marble contains 3 g of carbon and 8 g of oxygen in a sample. In another sample, made by burning charcoal, 12 g of carbon combine with 32 g of oxygen.\n(i) Find the mass of carbon dioxide in each sample.\n(ii) Find the ratio of carbon to oxygen in each.\n(iii) Name the law that is illustrated.", "(i) First sample: 3 + 8 = 11 g. Second sample: 12 + 32 = 44 g.\n(ii) 3 : 8 in the first sample and 12 : 32 = 3 : 8 in the second.\n(iii) The law of definite proportions.", "case"),
      W(5, "Write the formulae of magnesium nitrate, calcium chloride and aluminium oxide by the criss-cross method. Calculate the formula unit mass of the first two (Mg = 24, N = 14, O = 16, Ca = 40, Cl = 35.5 u).", "Magnesium nitrate: Mg²⁺ and NO₃⁻ give Mg(NO₃)₂.\nCalcium chloride: Ca²⁺ and Cl⁻ give CaCl₂.\nAluminium oxide: Al³⁺ and O²⁻ give Al₂O₃.\nMass of Mg(NO₃)₂ = 24 + 2 × (14 + 48) = 24 + 124 = 148 u.\nMass of CaCl₂ = 40 + 2 × 35.5 = 111 u.", "long"),
    ],
  },
    "sound-waves-characteristics-and-applications": {
    mcq: [
      M(1, "Sound is produced by", "vibrating objects", ["objects at rest", "a vacuum", "light"], "A tuning fork or a stretched string vibrates to make sound."),
      M(1, "A compression in a sound wave is a region of", "high density", ["low density", "zero density", "high temperature only"], "Compressions are high-density regions, and rarefactions are low-density regions."),
      M(1, "The time period T of a wave is related to its frequency ν by", "T = 1/ν", ["T = ν", "T = ν²", "T = 1 × ν"], "The period is the time for one oscillation, which is the reciprocal of the frequency."),
      M(1, "A sound wave of larger amplitude carries", "more energy", ["less energy", "no energy", "the same energy in all cases"], "Amplitude is the maximum change in density, and a larger one means more energy."),
      M(1, "In which medium is the speed of sound the least?", "A gas", ["A liquid", "A solid", "Steel"], "Sound travels fastest in solids and slowest in gases."),
      M(1, "Sound waves of frequency above 20 kHz are", "ultrasonic", ["infrasonic", "audible", "seismic"], "Below 20 Hz is infrasonic, and above 20 kHz is ultrasonic."),
      M(1, "Bats and dolphins find objects using", "echolocation", ["sonar boats", "infrasonic seismographs", "light"], "They send ultrasonic sound and use the reflected echo."),
      M(1, "A sound wave moving through air carries", "energy and not matter", ["matter and not energy", "both matter and energy", "neither energy nor matter"], "The wave passes on energy, but the air itself does not travel with it."),
      M(2, "A sound wave has a time period of 0.005 s and a wavelength of 1.7 m. Its speed is", "340 m s⁻¹", ["0.0085 m s⁻¹", "68 m s⁻¹", "2.1 m s⁻¹"], "ν = 1 ÷ 0.005 = 200 Hz. v = νλ = 200 × 1.7 = 340 m s⁻¹."),
      M(2, "A sound of frequency 680 Hz travels in air at 340 m s⁻¹. Its wavelength is", "0.5 m", ["2 m", "231 200 m", "340 m"], "λ = v ÷ ν = 340 ÷ 680 = 0.5 m."),
      M(2, "A vibrating object makes 30 oscillations in 3 s. Its frequency and period are", "10 Hz and 0.1 s", ["90 Hz and 0.011 s", "0.1 Hz and 10 s", "30 Hz and 3 s"], "ν = 30 ÷ 3 = 10 Hz. T = 1 ÷ 10 = 0.1 s."),
      M(2, "A source vibrates at 50 Hz. Its time period is", "0.02 s", ["50 s", "0.2 s", "2 s"], "T = 1 ÷ ν = 1 ÷ 50 = 0.02 s."),
      M(2, "A wall is 68 m from a girl who shouts. She hears the echo after", "0.4 s", ["0.2 s", "0.1 s", "2 s"], "The sound travels 68 + 68 = 136 m. Time = 136 ÷ 340 = 0.4 s."),
      M(2, "A boy shouts near a wall 10 m away. Why does he not hear a separate echo?", "The echo comes back in less than 0.1 s, so it merges with the original sound", ["Walls never reflect sound", "The sound travels too slowly to reach the wall", "The echo takes more than 0.1 s"], "Sound needs 20 ÷ 340 ≈ 0.06 s to go and return, which is less than 0.1 s."),
      M(2, "A ship's sonar signal returns after 3 s. The speed of sound in water is 1500 m s⁻¹. The depth of the sea is", "2250 m", ["4500 m", "1500 m", "500 m"], "The one-way time is 1.5 s. Depth = 1500 × 1.5 = 2250 m."),
      M(2, "A hall with bare, hard walls has more reverberation because hard, smooth surfaces", "reflect sound well", ["absorb sound well", "scatter sound in all directions only", "make sound travel faster"], "Soft materials such as curtains absorb sound and reduce reverberation."),
      M(2, "A 300 Hz sound wave travels in water at 1500 m s⁻¹. Its wavelength is", "5 m", ["0.2 m", "450 000 m", "50 m"], "λ = v ÷ ν = 1500 ÷ 300 = 5 m."),
      M(2, "A sound of frequency 10 Hz is", "infrasonic", ["ultrasonic", "in the audible range", "faster than light"], "Below 20 Hz, the sound is infrasonic."),
      M(2, "Which of these frequencies is in the audible range of a human ear?", "15 kHz", ["10 Hz", "30 kHz", "50 kHz"], "The audible range is 20 Hz to 20 kHz."),
      M(2, "On the Moon, astronauts use radios to talk to each other because", "there is no air, and sound cannot travel in a vacuum", ["the Moon is too hot", "sound is too loud there", "sound is too slow in rock"], "Sound needs a material medium."),
      M(3, "A person claps near a cliff and hears the echo after 1.2 s. The speed of sound is 340 m s⁻¹. The cliff is at a distance of", "204 m", ["408 m", "102 m", "283 m"], "Distance = speed × time ÷ 2 = 340 × 1.2 ÷ 2 = 204 m."),
      M(3, "A 250 Hz sound passes from air (340 m s⁻¹) into water (1500 m s⁻¹). In water its", "frequency stays 250 Hz and its wavelength is 6 m", ["frequency becomes 1500 Hz and its wavelength stays 1.36 m", "frequency stays 250 Hz and its wavelength is 1.36 m", "frequency falls to 56 Hz and its wavelength is 6 m"], "The frequency is fixed by the source. λ = 1500 ÷ 250 = 6 m, which is more than the 1.36 m in air."),
      M(3, "Sonar finds the depth of the sea by using the", "time taken by a reflected ultrasonic signal to return", ["time taken by light to reach the sea bed", "colour of the sea water", "temperature of the sea bed"], "The depth = speed of sound × half the time taken for the echo to return."),
      AR(3, "A distinct echo can be heard when the reflecting surface is at least 17 m away.", "The sound must take at least 0.1 s to return.", 0, "Both are true. At 340 m s⁻¹, a 0.1 s gap needs a 34 m round trip, which is 17 m each way."),
      AR(3, "The pitch of a sound depends on its frequency.", "A sound of higher frequency is shriller.", 0, "Both are true. Pitch is how the frequency is perceived."),
    ],
    written: [
      W(1, "Define the time period of a wave and write its relation with frequency.", "The time period is the time taken for one complete oscillation. T = 1/ν, where ν is the frequency.", "short"),
      W(1, "What is echolocation? Name one animal that uses it.", "Echolocation is the finding of objects by sending out ultrasonic sound and listening to the reflected sound. Bats and dolphins use it.", "short"),
      W(2, "An object makes 30 oscillations in 3 s. Find its frequency and time period.", "ν = 30 ÷ 3 = 10 Hz. T = 1 ÷ ν = 0.1 s.", "short"),
      W(2, "Why can sound not travel on the Moon?", "Sound needs a material medium to travel as compressions and rarefactions. The Moon has no air, so there is a vacuum around it and sound cannot travel.", "short"),
      W(2, "A girl shouts at a wall 68 m away. After how much time does she hear the echo? (speed of sound = 340 m s⁻¹)", "The sound travels 68 + 68 = 136 m. Time = distance ÷ speed = 136 ÷ 340 = 0.4 s.", "short"),
      W(2, "How is infrasound useful?", "Infrasound helps to detect earthquakes, volcanoes and storms.", "short"),
      W(3, "A 250 Hz sound wave passes from air (340 m s⁻¹) into water (1500 m s⁻¹). Find the wavelength in each and state what happens to the frequency.", "In air λ = 340 ÷ 250 = 1.36 m. In water λ = 1500 ÷ 250 = 6 m. The frequency stays 250 Hz, since it is fixed by the source.", "short"),
      W(3, "A sonar device finds that the sea bed is 750 m below the ship. Find the time after which the echo of its signal is received (speed of sound in sea water = 1500 m s⁻¹). State the principle of sonar.", "The signal travels 750 m down and 750 m up, so the distance = 1500 m. Time = 1500 ÷ 1500 = 1 s. Sonar sends ultrasonic waves, and the depth or the position of an object is found from the time taken by the reflected waves to return.", "short"),
      W(4, "Case study: A teacher notices that in a large hall with bare walls her voice seems to persist and the words overlap. After curtains and cushioned seats are put in, her words are clearer.\n(i) Name the phenomenon.\n(ii) Why does it occur in the bare hall?\n(iii) Why did the curtains and seats help?", "(i) Reverberation.\n(ii) Hard, smooth walls reflect sound many times, so the sound persists and overlaps.\n(iii) Soft materials absorb the sound, so there are fewer reflections and the sound dies away quickly.", "case"),
      W(5, "A boy stands 85 m from a hill and shouts (speed of sound = 340 m s⁻¹). (a) After how long does he hear the echo? (b) He moves 34 m further away. After how long will he hear the echo now? (c) He then stands only 8.5 m from the hill. Will he hear a distinct echo? Explain.", "(a) The sound travels 85 × 2 = 170 m. Time = 170 ÷ 340 = 0.5 s.\n(b) Distance = 119 m, so the sound travels 238 m. Time = 238 ÷ 340 = 0.7 s.\n(c) At 8.5 m the sound travels 17 m, which takes 17 ÷ 340 = 0.05 s. This is less than 0.1 s, so the echo merges with the original sound and is not heard separately. (A distinct echo needs a distance of at least 17 m.)", "long"),
    ],
  },
    "reproduction-how-life-continues": {
    mcq: [
      M(1, "Which of these reproduces asexually?", "Yeast", ["A hen that lays eggs after mating", "A mango tree that forms seeds after pollination", "A human being"], "Yeast, bacteria, amoeba and hydra reproduce asexually, with one parent."),
      M(1, "A potato plant can reproduce vegetatively from its", "stem", ["seed only", "flower only", "fruit only"], "Potato and ginger are stems that give rise to new plants."),
      M(1, "Sexual reproduction involves", "two parents and the fusion of gametes", ["one parent only", "no gametes", "only spores"], "Male and female gametes fuse to form a zygote."),
      M(1, "The fusion of a male gamete and a female gamete is called", "fertilisation", ["pollination", "ovulation", "menstruation"], "The zygote formed by fertilisation is the first cell of a new individual."),
      M(1, "Wheat and maize are usually pollinated by", "wind", ["water", "birds", "bats"], "Their pollen is light, and the stigma is feathery."),
      M(1, "Vallisneria is a plant that is pollinated by", "water", ["wind", "insects", "birds"], "Water carries the pollen of Vallisneria."),
      M(1, "In a woman, the fertilised egg gets implanted in the", "lining of the uterus", ["oviduct", "ovary", "skin"], "The zygote implants in the uterus lining and pregnancy begins."),
      M(1, "After fertilisation in a flower, the ovule becomes the", "seed", ["fruit", "pollen grain", "stigma"], "The ovule becomes the seed and the ovary becomes the fruit."),
      M(2, "A cutting of a money plant grows into a new plant. This is an example of", "vegetative propagation", ["sexual reproduction", "pollination", "spore formation"], "A new plant grows from a vegetative part, a stem cutting."),
      M(2, "Farmers use cutting, grafting and layering because these methods", "give many plants like the parent plant with the desired features", ["produce plants with different characters from the parent", "need two parents", "need pollination"], "They are forms of asexual reproduction, so the offspring are identical to the parent."),
      M(2, "If human gametes had 46 chromosomes each, the zygote would have", "92 chromosomes", ["46 chromosomes", "23 chromosomes", "69 chromosomes"], "46 + 46 = 92. This is why meiosis halves the number in the gametes."),
      M(2, "A plant has 20 chromosomes in its body cells. Its gametes and its zygote have", "10 and 20 chromosomes", ["20 and 20 chromosomes", "10 and 10 chromosomes", "20 and 40 chromosomes"], "Meiosis halves the number in the gametes (10), and fertilisation restores it in the zygote (10 + 10 = 20)."),
      M(2, "Bright, scented flowers with nectar are mostly pollinated by", "insects and birds", ["wind", "water", "no agent"], "Insects and birds are attracted by bright colours, scent and nectar."),
      M(2, "A feathery stigma is suited to", "wind pollination", ["insect pollination", "water pollination only", "self-pollination only"], "A feathery stigma can catch the light pollen carried in the air."),
      M(2, "After pollination, the pollen tube grows through the style to the", "ovule", ["anther", "petal", "leaf"], "The male gamete passes down the pollen tube and fuses with the egg in the ovule."),
      M(2, "Menstruation lasts about", "3 to 7 days", ["15 to 20 days", "9 months", "1 day only"], "If the egg is not fertilised, the uterine lining is shed for 3–7 days."),
      M(2, "The length of the menstrual cycle is usually", "21 to 35 days, about 28 on average", ["3 to 7 days", "9 months", "about 2 days"], "The cycle repeats every 21–35 days."),
      M(2, "In humans, pregnancy lasts about", "nine months", ["nine days", "three months", "two years"], "A zygote implanted in the uterus develops over about nine months."),
      M(2, "Prenatal sex determination in India is", "prohibited by law", ["encouraged by law", "required by law", "permitted for everyone"], "The law prohibits prenatal sex determination."),
      M(2, "Variation among the offspring of sexual reproduction helps the species because it", "helps the species to adapt and survive", ["makes all the offspring identical", "stops reproduction", "removes all differences"], "Variation helps some individuals to survive when conditions change."),
      M(2, "In lizards and birds, fertilisation takes place", "inside the female's body", ["in water outside the body", "only in plants", "after the eggs are laid"], "Internal fertilisation leads to fewer eggs and better survival of the young."),
      M(3, "Pollen from the anther falls on the stigma of another flower on the same plant. This is", "self-pollination", ["cross-pollination", "fertilisation", "vegetative propagation"], "Self-pollination includes the transfer to the same flower or to another flower of the same plant."),
      AR(3, "Sexual reproduction produces variation among offspring.", "The genes of two parents are mixed, and meiosis creates new combinations.", 0, "Both are true, and the mixing of genes is why the offspring differ."),
      AR(3, "Offspring formed by vegetative propagation are identical to the parent plant.", "Only one parent is involved in vegetative propagation.", 0, "Both are true. With one parent there is no mixing of genes."),
      AR(3, "Pollination and fertilisation are the same process.", "Pollination is the transfer of pollen, and fertilisation is the fusion of gametes.", 3, "A is false, since they are different steps. R is true."),
      M(3, "Which is the correct order of events in human reproduction?", "Ovulation, fertilisation in the oviduct, implantation in the uterus, pregnancy", ["Implantation, ovulation, fertilisation, pregnancy", "Fertilisation, ovulation, pregnancy, implantation", "Ovulation, implantation, fertilisation, pregnancy"], "The egg is released first, fertilised in the oviduct, and the zygote then implants in the uterus."),
    ],
    written: [
      W(1, "Name two organisms that reproduce asexually.", "Bacteria, amoeba, yeast, hydra and sponge (any two).", "short"),
      W(1, "What is the usual length of the menstrual cycle?", "It is about 28 days, in a range of 21 to 35 days.", "short"),
      W(2, "Why are the new plants obtained by vegetative propagation identical to the parent plant?", "Only one parent is involved and the new plant grows from a part of it by cell division, so there is no mixing of genes from two parents. The offspring have the same genes as the parent.", "short"),
      W(2, "What do the ovule and the ovary of a flower become after fertilisation?", "The ovule becomes the seed and the ovary becomes the fruit.", "short"),
      W(2, "State two features of a flower that is pollinated by insects.", "It has bright colours and a scent, and it produces nectar to attract insects and birds (any two).", "short"),
      W(2, "The body cells of an animal have 36 chromosomes. How many chromosomes are there in its gametes and in the zygote? Explain.", "The gametes have 18 chromosomes, since meiosis halves the number. At fertilisation two gametes fuse, so the zygote has 18 + 18 = 36 chromosomes.", "short"),
      W(3, "Explain the role of the pollen tube in fertilisation.", "After a pollen grain lands on the stigma, it forms a pollen tube. The tube grows down through the style to the ovule. The male gamete passes through it and fuses with the egg in the ovule, which is fertilisation.", "short"),
      W(3, "Why does sexual reproduction give variation? How is it useful to a species?", "In sexual reproduction two parents are involved, so their genes are mixed, and meiosis gives new combinations. The offspring therefore differ from the parents and from one another. This variation helps the species to adapt and survive when conditions change.", "short"),
      W(4, "Case study: Sunita grows a new rose plant from a stem cutting. Her mother sows a mango seed, which grows into a tree.\n(i) Name the type of reproduction in each case.\n(ii) In which case will the new plant be identical to the parent?\n(iii) In which case does variation arise, and why?", "(i) The rose: asexual reproduction (vegetative propagation by cutting). The mango seed: sexual reproduction.\n(ii) The rose from the cutting.\n(iii) The mango seed, because it forms from the fusion of gametes of two parents, which mixes their genes.", "case"),
      W(5, "Compare external and internal fertilisation in animals. Give examples, state the number of eggs laid, and say how the survival of the young differs.", "External fertilisation takes place in water outside the body, as in fish and frogs. They lay hundreds to thousands of eggs, and the young have a low chance of survival.\nInternal fertilisation takes place inside the female's body, as in lizards and birds. They lay fewer eggs, and the young have a better chance of survival.", "long"),
    ],
  },
    "patterns-in-life-diversity-and-classification": {
    mcq: [
      M(1, "Biodiversity means", "the variety of living organisms on Earth", ["the number of humans in India", "the study of rocks", "the total weight of all plants"], "Biodiversity is the variety of life, and classification helps to study it."),
      M(1, "Unicellular eukaryotes such as Euglena belong to the kingdom", "Protista", ["Monera", "Fungi", "Animalia"], "Protista includes Amoeba, Paramecium and Euglena."),
      M(1, "Cyanobacteria belong to the kingdom", "Monera", ["Protista", "Plantae", "Fungi"], "Monera has unicellular prokaryotes such as bacteria and cyanobacteria."),
      M(1, "Ferns belong to the group", "Pteridophyta", ["Bryophyta", "Thallophyta", "Gymnosperms"], "Pteridophyta are the ferns."),
      M(1, "Mosses belong to the group", "Bryophyta", ["Pteridophyta", "Angiosperms", "Thallophyta"], "Bryophyta are the mosses."),
      M(1, "Algae are placed in the group", "Thallophyta", ["Bryophyta", "Gymnosperms", "Angiosperms"], "Thallophyta are the algae."),
      M(1, "Flatworms show", "bilateral symmetry", ["no tissues", "only one opening and true tissues", "a notochord"], "Platyhelminthes show bilateral symmetry. Sponges have no tissues and Hydra has one opening."),
      M(1, "In the scientific name Panthera tigris, the genus is", "Panthera", ["tigris", "Panthera tigris", "tiger"], "The first word is the genus and the second is the species."),
      M(2, "The scientific name of the tiger is written as", "Panthera tigris, with the genus name first", ["Tigris panthera, with the species name first", "Panthera leo, with the genus name first", "Mangifera tigris, with the genus of the mango"], "In binomial nomenclature the genus name comes first, with a capital letter, and then the species name in small letters. Panthera leo is the lion."),
      M(2, "Autotrophic organisms are those that", "make their own food", ["depend on other organisms for food", "feed on dead matter only", "never need food"], "Green plants are autotrophs. Heterotrophs get their food from other organisms."),
      M(2, "Which kingdom has multicellular organisms that are autotrophic and have a cellulose cell wall?", "Plantae", ["Animalia", "Fungi", "Monera"], "Plants make food by photosynthesis and have cellulose cell walls."),
      M(2, "Sponges belong to Porifera. Which feature do they have?", "No true tissues", ["True tissues and one opening", "A notochord", "Bilateral symmetry"], "Sponges are the simplest of the three invertebrate groups studied."),
      M(2, "Which is the lowest group in the taxonomic hierarchy?", "Species", ["Kingdom", "Family", "Phylum"], "The order is Kingdom, Phylum, Class, Order, Family, Genus, Species."),
      M(2, "Two organisms from the same genus are expected to share more features than two organisms from the same", "family but different genera", ["genus", "species", "population"], "Lower groups in the hierarchy share more features."),
      M(2, "Fossils are useful because they", "show how life has changed over time", ["are living organisms", "prove all species are equal", "are made by Linnaeus"], "Fossils are preserved remains of ancient organisms."),
      M(2, "Birbal Sahni is known for his study of", "fossil plants", ["fossil insects", "bacteria", "ocean currents"], "He was a scientist who studied fossil plants."),
      M(2, "The Sangai deer is found on", "the phumdis of Loktak lake", ["Himalayan snow", "the Thar desert", "coral reefs"], "The Sangai deer of the phumdis of Loktak is endangered."),
      M(2, "Which of these is a threat to biodiversity?", "Deforestation", ["Planting native trees", "Protecting habitats", "Saving water"], "Pollution, deforestation, overuse of resources and climate change reduce biodiversity."),
      M(2, "Linnaeus first divided living things into", "two kingdoms", ["three kingdoms", "four kingdoms", "five kingdoms"], "Linnaeus used two kingdoms. Haeckel used three, Copeland four and Whittaker five."),
      M(2, "Pine is a gymnosperm because its seeds are", "naked, not enclosed in a fruit", ["enclosed in a fruit", "not formed at all", "formed inside the root"], "Gymnosperms have naked seeds, and angiosperms have flowers and enclosed seeds."),
      M(2, "Whether an animal has a notochord decides whether it is", "a chordate or a non-chordate", ["a plant or an animal", "a prokaryote or an eukaryote", "a producer or a consumer"], "Animals are first divided into non-chordates and chordates by the notochord."),
      M(3, "An organism is unicellular, has a nucleus, makes its own food with chlorophyll and moves about. It belongs to the kingdom", "Protista", ["Monera", "Fungi", "Plantae"], "It is a unicellular eukaryote, like Euglena."),
      M(3, "Which row is correct?", "Fungi — chitin cell walls and heterotrophic; Plantae — cellulose cell walls and autotrophic", ["Fungi — autotrophic with cellulose walls; Plantae — heterotrophic with chitin walls", "Fungi — prokaryotic and unicellular; Plantae — no cell wall", "Fungi — no cell wall; Plantae — chitin cell walls"], "Fungi are heterotrophic decomposers with chitin cell walls."),
      AR(3, "Fungi are decomposers.", "Fungi are heterotrophic and feed on dead matter.", 0, "Both are true, and feeding on dead matter is what makes them decomposers."),
      AR(3, "A scientific name has two parts.", "Binomial nomenclature uses a genus name and a species name.", 0, "Both are true, and the two names are the genus and the species."),
      AR(3, "Bacteria are placed in the kingdom Monera.", "Bacteria do not have a membrane-bound nucleus.", 0, "Both are true. Monera has unicellular prokaryotes."),
    ],
    written: [
      W(1, "Name the kingdom whose members have cell walls made of chitin.", "Fungi.", "short"),
      W(1, "Give two examples of members of the kingdom Protista.", "Amoeba, Paramecium and Euglena (any two).", "short"),
      W(2, "Differentiate between autotrophic and heterotrophic nutrition with an example of each.", "Autotrophs make their own food, for example green plants by photosynthesis. Heterotrophs depend on other organisms for food, for example animals and fungi.", "short"),
      W(2, "What are fossils? Name a scientist who studied them.", "Fossils are the preserved remains or impressions of ancient organisms. They show how life has changed. Birbal Sahni studied fossil plants.", "short"),
      W(2, "Why do two organisms of the same genus share more features than two organisms of the same family?", "The taxonomic hierarchy goes from the broad kingdom to the narrow species, and the lower groups share more features. A genus is a smaller group than a family and lies below it, so its members are more alike.", "short"),
      W(3, "Name the five groups of plants with one example of each.", "Thallophyta — algae; Bryophyta — mosses; Pteridophyta — ferns; Gymnosperms — pine; Angiosperms — flowering plants such as mango.", "short"),
      W(3, "Write two features each of the kingdoms Monera and Protista.", "Monera: unicellular prokaryotes with no well-defined nucleus; includes bacteria and cyanobacteria; some have cell walls and are autotrophic or heterotrophic. Protista: unicellular eukaryotes with a nucleus; examples are Amoeba, Paramecium and Euglena.", "short"),
      W(3, "State three threats to biodiversity and two ways to protect it.", "Threats: pollution, deforestation, overuse of resources and climate change (any three). Protection: protecting habitats, planting trees, saving resources, reducing pollution (any two).", "short"),
      W(4, "Case study: A student records three organisms. D is multicellular, has a body of fine threads (mycelium) and a cell wall of chitin. E is unicellular, has a nucleus and moves about. F is unicellular and has no nucleus.\n(i) Name the kingdom of each organism.\n(ii) Is D autotrophic or heterotrophic?\n(iii) Give one example of E.", "(i) D — Fungi; E — Protista; F — Monera.\n(ii) Heterotrophic (a fungus feeds on other matter and cannot make its own food).\n(iii) Amoeba (or Paramecium or Euglena).", "case"),
      W(5, "Describe how the systems of classification developed from Aristotle to Whittaker. State why a classification system is needed.", "Aristotle grouped organisms by their habitat. Linnaeus proposed two kingdoms, plants and animals. Haeckel suggested three kingdoms and Copeland four. Whittaker proposed the five kingdoms in 1969: Monera, Protista, Fungi, Plantae and Animalia, based on cell type, body organisation and mode of nutrition.\nClassification is needed because there is a huge variety of life. Grouping organisms by their similarities and differences makes them easy to study and shows how they are related.", "long"),
    ],
  },
    "earth-as-a-system-energy-matter-and-life": {
    mcq: [
      M(1, "The Earth's surface is heated unevenly because of its shape, latitude and", "the tilt of its axis", ["its distance from the Moon", "its colour", "the number of its oceans"], "These factors make the incoming solar radiation (insolation) uneven."),
      M(1, "Which surface warms up the most in bright sunshine?", "Dark soil", ["Fresh snow", "Ice", "A white roof"], "Dark surfaces have low albedo and absorb more heat."),
      M(1, "In the stratosphere, the temperature with height", "rises", ["falls", "stays the same", "becomes zero"], "The ozone layer absorbs UV radiation, so the temperature rises with height."),
      M(1, "The layer of the atmosphere that is nearest to the ground is the", "troposphere", ["stratosphere", "ozone layer", "exosphere"], "The troposphere extends from 0 to about 12 km."),
      M(1, "A mountain breeze blows", "down into the valley at night", ["up the slope by day", "from the sea by day", "only in the plains"], "At night the air flows down the slopes into the valley."),
      M(1, "Which of these is a biogeochemical cycle?", "The carbon cycle", ["The rock-hardening cycle", "The moon cycle", "The fuel cycle"], "The water, carbon, nitrogen and oxygen cycles move matter between living and non-living parts."),
      M(1, "The atmosphere is held around the Earth by", "gravity", ["magnetism only", "winds", "ocean currents"], "Gravity holds the gases close to the Earth."),
      M(2, "A surface has an albedo of 0.2 and receives 500 units of sunlight. The amount reflected is", "100 units", ["400 units", "20 units", "250 units"], "Albedo is the fraction reflected: 0.2 × 500 = 100 units."),
      M(2, "A surface with an albedo of 0.2 absorbs what fraction of the sunlight?", "0.8", ["0.2", "0.4", "1.2"], "The fraction absorbed = 1 − 0.2 = 0.8."),
      M(2, "The ground temperature is 35 °C. The temperature falls by about 6.5 °C per km in the troposphere. At a height of 2 km it is about", "22 °C", ["13 °C", "28.5 °C", "48 °C"], "Fall = 2 × 6.5 = 13 °C. Temperature = 35 − 13 = 22 °C."),
      M(2, "On a sunny day the sand on a beach is much hotter than the sea water. This is because", "land heats up faster than water", ["water heats up faster than land", "sand has a high albedo", "the sea reflects no sunlight"], "Land heats up faster than water."),
      M(2, "At the equatorial low-pressure belt, the warm air", "rises", ["sinks", "stays still", "turns into ocean current"], "Warm air rises at the equator, moves poleward and sinks near 30° N and S."),
      M(2, "Ocean currents are affected by", "winds, differences in temperature and salinity, Earth's rotation and the shape of land masses", ["only the Moon", "only fish", "only rivers"], "These are the main factors listed for ocean currents."),
      M(2, "The planetary wind pattern is completed when the air returns to the equator along the", "surface", ["stratosphere", "ozone layer", "mountain tops"], "Air sinks near 30° N and S and flows back to the equator near the surface."),
      M(2, "Polar ice caps help to keep the Earth cooler because they", "reflect much of the sunlight, as they have a high albedo", ["absorb all the sunlight", "make the air warm", "release heat"], "Snow and ice reflect 80–90% of the radiation."),
      M(2, "Which of these helps to reduce greenhouse gases in the air?", "Planting trees", ["Burning more fuels", "Clearing forests", "Using more coal"], "Trees take in carbon dioxide. Renewable energy and reduce–reuse–recycle also help."),
      M(2, "Smog and ground-level ozone are mainly caused by", "human activities such as burning fuels", ["the ozone layer in the stratosphere", "winds from the poles", "ocean currents"], "Burning fuels and other human activities add pollutants to the air."),
      M(2, "Clearing forests can affect", "rainfall and biodiversity", ["only the Moon", "nothing in the atmosphere", "the speed of light"], "Deforestation changes the carbon cycle, the rainfall and the habitats of organisms."),
      M(2, "Oxygen from the atmosphere is used in", "combustion, respiration and the formation of oxides", ["photosynthesis only", "the making of nitrogen", "ocean currents only"], "Photosynthesis, on the other hand, restores the oxygen."),
      M(2, "A plane flies at a height of 10 km. The outside temperature is −35 °C. Taking a fall of 6.5 °C per km, the ground temperature is about", "30 °C", ["−100 °C", "−28.5 °C", "65 °C"], "Fall = 10 × 6.5 = 65 °C. Ground = −35 + 65 = 30 °C."),
      M(3, "Snow has an albedo of about 0.8. Of 400 units of sunlight falling on it, the amount absorbed is about", "80 units", ["320 units", "400 units", "0.8 units"], "Reflected = 0.8 × 400 = 320 units. Absorbed = 400 − 320 = 80 units."),
      M(3, "Snow in a region melts and exposes dark ground. What is the likely effect?", "More sunlight is absorbed, so the region warms further", ["More sunlight is reflected, so it cools", "Nothing changes", "The albedo increases"], "Dark ground has a low albedo, and absorbs more of the solar radiation."),
      AR(3, "The temperature rises with height in the stratosphere.", "The ozone layer there absorbs ultraviolet radiation.", 0, "Both are true, and the heat given by the absorption of UV is why the temperature rises."),
      AR(3, "Dark soil warms up more than snow in the sunshine.", "Dark soil has a lower albedo than snow.", 0, "Both are true. A lower albedo means more radiation is absorbed."),
      AR(3, "The valley breeze blows up the slope during the day.", "The air over the sun-warmed slope becomes warm and rises.", 0, "Both are true. The warm air rises up the slope, and cooler air from the valley takes its place."),
    ],
    written: [
      W(1, "Name the two lowest layers of the atmosphere and state their heights.", "The troposphere, from 0 to about 12 km, and the stratosphere, from about 12 to 50 km.", "short"),
      W(1, "Name the international agreement that helped the ozone layer to recover.", "The Montreal Protocol.", "short"),
      W(2, "The ground temperature is 35 °C. Find the temperature at a height of 4 km in the troposphere, if the fall is 6.5 °C per km.", "Fall = 4 × 6.5 = 26 °C. Temperature = 35 − 26 = 9 °C.", "short"),
      W(2, "On a sunny afternoon, why is the sand on a beach hotter than the sea water?", "Land heats up faster than water, so the sand becomes hotter than the sea water in the same sunshine.", "short"),
      W(2, "What is a mountain breeze? When does it blow and why?", "A mountain breeze blows down the slope into the valley at night. The slopes cool at night, so the cooler air flows down into the valley.", "short"),
      W(2, "How is oxygen used up in nature, and how is it restored?", "Oxygen is used in combustion, respiration and the formation of oxides. It is restored mainly by photosynthesis in plants.", "short"),
      W(3, "Explain how the melting of polar ice can lead to further warming.", "Ice has a high albedo and reflects most of the sunlight. When it melts, it exposes dark ocean water or ground, which has a low albedo and absorbs more radiation. So the region absorbs more heat and warms further, which melts more ice.", "short"),
      W(3, "Name three human activities that affect the atmosphere. Give one remedy for each.", "Burning fuels (use renewable energy), deforestation (plant trees), and the making of waste and pollution (reduce, reuse, recycle). Saving water is another remedy.", "short"),
      W(4, "Case study: Fresh snow, desert sand and a forest have albedos of 0.8, 0.4 and 0.1. Each receives 500 units of sunlight.\n(i) How much sunlight does each surface reflect?\n(ii) Which one absorbs the most?\n(iii) Which one will stay the coolest and why?", "(i) Snow: 0.8 × 500 = 400 units. Desert sand: 0.4 × 500 = 200 units. Forest: 0.1 × 500 = 50 units.\n(ii) The forest, which absorbs 450 units.\n(iii) Fresh snow, because it has the highest albedo and reflects most of the sunlight.", "case"),
      W(5, "Describe the two lowest layers of the atmosphere with their height, the change of temperature with height and one important feature of each. State the rate of fall of temperature in the lower layer.", "Troposphere: from 0 to about 12 km. The temperature falls with height, at about 6.5 °C per km. All the weather occurs here, because it holds most of the air and water vapour.\nStratosphere: from about 12 to 50 km. The temperature rises with height because the ozone layer there absorbs the harmful ultraviolet radiation from the Sun. Weather is confined to the troposphere.", "long"),
    ],
  },
    });
})();
